#!/bin/bash
# run_exec: $1 = script generated by the runner for this stage, $2 = stage name.
# The script is piped into bash on the job VM; its exit code decides build vs system failure.
set -uo pipefail
# shellcheck source=common.sh
. "$(dirname "$0")/common.sh"

script=${1:?script path}
stage=${2:-unknown}
load_vm || exit "$SYSTEM_FAILURE_EXIT_CODE"

job_ssh bash -s < "$script"
rc=$?
[ "$rc" -eq 0 ] && exit 0

# ssh itself returns 255 on connection errors; tell that apart from a script that exited 255.
if [ "$rc" -eq 255 ] && ! job_ssh true </dev/null 2>/dev/null; then
  echo "executor: lost ssh to VM $VM_ID during $stage" >&2
  exit "$SYSTEM_FAILURE_EXIT_CODE"
fi
exit "$BUILD_FAILURE_EXIT_CODE"
